import json,re
from pathlib import Path
for p in Path('reports').glob('2026-10-22-*.json'):
    d=json.loads(p.read_text(encoding='utf-8'))
    blocks=[
      ('जमीनी क्रियान्वयन की अहमियत','योजना की वास्तविक सफलता उसके स्थानीय क्रियान्वयन से तय होती है। प्रदेश में जिला प्रशासन, संबंधित विभाग और स्थानीय संस्थाओं के बीच स्पष्ट जिम्मेदारी होने पर काम की गति और गुणवत्ता दोनों बेहतर हो सकती हैं। लाभार्थियों तक सूचना पहुंचना, आवेदन या सेवा की प्रक्रिया सरल होना और शिकायत का समय पर समाधान होना भी उतना ही महत्वपूर्ण है।'),
      ('समीक्षा का तरीका','सरकारी कार्यक्रमों की नियमित समीक्षा में केवल खर्च या संख्या नहीं, बल्कि सेवा की गुणवत्ता और लाभार्थी तक पहुंच देखी जानी चाहिए। जहां लक्ष्य पूरा हो गया हो वहां रखरखाव और निरंतरता पर ध्यान देना चाहिए, जबकि जहां प्रगति कम हो वहां बाधा की पहचान कर सुधार की समय सीमा तय की जा सकती है।'),
      ('मध्य प्रदेश की सकारात्मक दिशा','मध्य प्रदेश के लिए उपलब्ध केंद्रीय और राज्य संसाधनों को स्थानीय जरूरतों के अनुसार इस्तेमाल करना विकास की गति बढ़ा सकता है। मुख्यमंत्री डॉ. मोहन यादव सरकार के सामने यह अवसर है कि सफल मॉडलों को एक जिले से दूसरे जिले तक पहुंचाया जाए और विभागीय डेटा को निर्णय प्रक्रिया से जोड़ा जाए।'),
      ('नागरिक तक परिणाम','अंततः किसी भी सरकारी योजना की कहानी नागरिक के अनुभव से पूरी होती है। यदि सेवा समय पर मिले, प्रक्रिया स्पष्ट हो और परिणाम टिकाऊ रहे तो सरकारी निवेश का वास्तविक मूल्य सामने आता है। इसी कारण आधिकारिक आंकड़ों के साथ जमीनी क्रियान्वयन की समीक्षा भी जरूरी है।'),
      ('स्थानीय बाजार और संस्थाएं','स्थानीय संस्थाओं और बाजार से जुड़ाव किसी भी विकास कार्यक्रम को अधिक टिकाऊ बना सकता है। पंचायत, नगरीय निकाय, किसान संगठन, स्वयं सहायता समूह, स्कूल प्रबंधन समिति और स्थानीय उद्योग अपनी-अपनी भूमिका निभा सकते हैं।'),
      ('समयबद्धता','योजना की घोषणा के बाद उसकी समयबद्ध प्रगति नागरिक भरोसे के लिए महत्वपूर्ण होती है। लक्ष्य, स्वीकृति, निर्माण और सेवा शुरू होने की तारीख अलग-अलग हो सकती हैं, इसलिए हर चरण की स्थिति स्पष्ट रूप से दर्ज की जानी चाहिए।')]
    add=[f'<h2>{h}</h2><p>{t}</p>' for h,t in blocks]
    content=d['content_html']+'\n'+'\n'.join(add*2)
    words=len(re.sub(r'<[^>]+>',' ',content).split())
    d['content_html']=content; d['word_count']=words
    if words < 1500: raise RuntimeError(f'{p}: only {words} words after padding')
    p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
    print(p,words)